∀ {toWorkers : outputs.Algorithms.FreyaInputs.Workers} {τ : Fin toWorkers.n → ENNReal}
  {toWorkers_1 : outputs.Algorithms.FreyaInputs.Workers} {τ_1 : Fin toWorkers_1.n → ENNReal},
  { toWorkers := toWorkers, τ := τ } = { toWorkers := toWorkers_1, τ := τ_1 } → toWorkers = toWorkers_1 ∧ τ ≍ τ_1

∀ {d m n : ℕ} {x0 : outputs.Proofs.FreyaModel.Space d} {η : ℝ} {S : ℕ} {ρ : ℝ} {K : ℕ} {«prefix» : Bool}
  {d_1 m_1 n_1 : ℕ} {x0_1 : outputs.Proofs.FreyaModel.Space d_1} {η_1 : ℝ} {S_1 : ℕ} {ρ_1 : ℝ} {K_1 : ℕ}
  {prefix_1 : Bool},
  { d := d, m := m, n := n, x0 := x0, η := η, S := S, ρ := ρ, K := K, «prefix» := «prefix» } =
      { d := d_1, m := m_1, n := n_1, x0 := x0_1, η := η_1, S := S_1, ρ := ρ_1, K := K_1, «prefix» := prefix_1 } →
    d = d_1 ∧ m = m_1 ∧ n = n_1 ∧ x0 ≍ x0_1 ∧ η = η_1 ∧ S = S_1 ∧ ρ = ρ_1 ∧ K = K_1 ∧ «prefix» = prefix_1
